import { extractEmojis } from 'unicode-emoji-utils';

export const emojiEncode = (msg: string) => {
    return Array.from(msg).map(char => {
        if (extractEmojis(char).length > 0) {
            const codePoint = char.codePointAt(0);
            return codePoint !== undefined ? `&amp;#${codePoint.toString(10)};` : char;
        }
        return char;
    }).join('');
};
